import{_ as e,c as t,o as i,ae as r}from"./chunks/framework.CHDT0Kbg.js";const _=JSON.parse('{"title":"認識 Persim","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/introduction.md","filePath":"zh-TW/guide/introduction.md","lastUpdated":1795170900000}'),l={name:"zh-TW/guide/introduction.md"};function o(n,a,s,d,h,c){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="認識-persim" tabindex="-1">認識 Persim <a class="header-anchor" href="#認識-persim" aria-label="Permalink to &quot;認識 Persim&quot;">​</a></h1><p>一個打開就能用的 Mac 瀏覽器：分頁、搜尋、書籤、下載，都在該在的位置。</p><h2 id="打開就會做什麼" tabindex="-1">打開就會做什麼 <a class="header-anchor" href="#打開就會做什麼" aria-label="Permalink to &quot;打開就會做什麼&quot;">​</a></h2><ul><li><strong>上網與搜尋</strong>：網址列既能輸入網址，也能直接搜尋；常去的地址會優先補全。</li><li><strong>多個分頁與視窗</strong>：新增、拖曳、分組、靜音、暫停預覽，按 ⌘⇧A 快速找到某個分頁。</li><li><strong>收藏與找回</strong>：書籤列、書籤管理員、歷史紀錄、下載中心，還有「恢復上次工作階段」。</li></ul><h2 id="想安靜一點" tabindex="-1">想安靜一點 <a class="header-anchor" href="#想安靜一點" aria-label="Permalink to &quot;想安靜一點&quot;">​</a></h2><ul><li>廣告攔截支援訂閱規則、自訂規則與白名單，信任的網站可以放行。</li><li>網頁強制深色、分頁靜音、彈窗攔截都在設定裡一鍵開關。</li><li>無痕視窗（⌘⇧N）不會寫下瀏覽紀錄。</li></ul><h2 id="看影片與讀長文" tabindex="-1">看影片與讀長文 <a class="header-anchor" href="#看影片與讀長文" aria-label="Permalink to &quot;看影片與讀長文&quot;">​</a></h2><ul><li>偵測面板列出頁面裡的影片，儲存後就是一個完整的 MP4，用你習慣的應用程式開啟即可。</li><li>閱讀模式（⌘⇧R）拿掉導覽和廣告，只留下正文；也可以擷取可視區或整頁 PDF。</li></ul><h2 id="按你的習慣來" tabindex="-1">按你的習慣來 <a class="header-anchor" href="#按你的習慣來" aria-label="Permalink to &quot;按你的習慣來&quot;">​</a></h2><p>淺色 / 深色 / 跟隨系統，六種主色，書籤列三種顯示方式，介面語言 25 種。外觀改完立刻生效，介面語言需要重新開啟視窗。</p>',10)])])}const m=e(l,[["render",o]]);export{_ as __pageData,m as default};
